GimCorpus.put(398,0,[[1,9,"תפלות אלו וכו'. כתב הראב\"ד ז\"ל אע\"פ שלא יחדש עכ\"ל:",1,0],[1,10,"אין הצבור מתפללין. וכתב הראב\"ד ז\"ל מצינו קרבן נדבה בצבור והיא עולה הבאה מן המותר שהיא קיץ למזבח אלא שלא היתה מצויה ומה שאמרו שלא יתפלל יחיד תפלת המוספים נדבה וכן מה שאמר הגאון שאסור להתפלל נדבה בשבתות ויו\"ט לפי שאין מקריבין בהן נדבות אלא חובת היום בלבד אני דעת אחרת יש עמי בכל אלה דרבי יוחנן לא אמר הלואי שיתפלל אדם כל היום אלא י\"ח שהיא תפלת רחמים ובקשה ושוהה ביניהן כדי שתתחולל דעתו עליו ויתכוין דעתו לבקש רחמים אבל תפלת שבת וי\"ט שאינו אלא הודאות לא אמר ר' יוחנן ואם יודה ויחזור ויודה ברכה לבטלה היא וכן ברכות יוצר וברכות דערבית וברכת המצות וברכת הפירות והדומה להן עכ\"ל:",1,0],[3,7,"ויש לו להתפלל וכו'. כתב הראב\"ד ז\"ל אין ראוי לעשות כן אלא לצורך שעה והלא צריך לסמוך גאולה לתפלה:",1,0],[3,10,"טעה ולא התפלל לא תפלה זו כו'. כתב הראב\"ד ראיתי בדעתו שאינו משלם טעות אלא בסמוך לו ולפיכך אמר שחרית אין לה תשלומין שכבר עבר זמנה ודעת יחידית היא זו מפני שראה הענין בסמוכין משחרית למנחה וממנחה לערבית ומערבית לשחרית ואני אין לי להורות בה לא איסור ולא היתר ואם רצה להשלים ישלים, אבל אני אומר אם נזכר בסמוכה לה ולא השלים טעותו ורוצה להשלים במופלגות אינו משלים מפני שהוא ביטול במזיד. עוד נ\"ל שכל אלו התשלומים שאמרו אינם אלא עם התפלה האחרת שבאה בזמנה הואיל ושעת תפלה היא:",1,0],[4,3,"אבל שחרית רוחץ פניו ידיו ורגליו כו'. כתב הראב\"ד ז\"ל לא ידעתי רגליו למה עכ\"ל:",1,0],[5,7,"לא יעמוד במקום גבוה כו' עד שהרי חלק רשות לעצמו. כתב הראב\"ד ז\"ל, א\"א ובכלל זה אם יכול לירד למטה ולהתפלל ירד למטה ויתפלל:",1,0],[5,14,"ואין אדם חשוב רשאי ליפול על פניו אלא אם כן יודע בעצמו שהוא צדיק כיהושע. א\"א בירושלמי ובלבד יחיד על הציבור ואית דגרסי ובלבד יחיד בציבור עכ\"ל:",1,0],[8,5,"וכן לא יהיה אחד מברך ברכת כו'. כתב הראב\"ד ז\"ל אינו אומר אלא יוצר בשביל קדושה שבה וזהו פורס כמו בפרוס הפסח מאי פרוס פלגא פלגא דהלכות הפסח וכן פורס על שמע והיא אחת מהשתים שלפניה עכ\"ל:",1,0],[10,5,"אף בלבנים לא יעבור. א\"א אנו אומרים מפני חשש מינות ולא באותה תפלה ולא בתפלה אחרת:",1,0],[10,6,"מי שהיה עומד בתפלה וכו'. כתב הראב\"ד ז\"ל אין כאן נחת רוח עכ\"ל:",1,0],[10,13,"עשרה ימים וכו'. כתב הראב\"ד ז\"ל יש מי שאומר שאינו חוזר לראש ומ\"ש בגמרא לא יצא לומר שלא יצא ידי חובת ברכה כתקנה ומצאנו בענין ק\"ש שאמרו הקורא עם אנשי משמר ועם אנשי מעמד לא יצא מפני שאנשי משמר מקדימין והדבר ידוע שהיו קורין אחר עמוד השחר ובשעת הדחק אדם יוצא בה ומאי לא יצא דקאמרינן אלא שלא יצא כתקנה וגם זה כמו זה עכ\"ל:",1,0],[12,15,"המפטיר בנביא כו' עד שנייה חותם בונה ירושלים כו' עד בתפלה. כתב הראב\"ד ז\"ל אנו אומרים משמח ציון בבניה עכ\"ל:",1,0],[13,6,"שמנה פסוקים שבסוף התורה כו' עד מותר ליחיד לקרותן. כתב הראב\"ד ז\"ל לא שמענו דבר זה מעולם ומה שאמרו יחיד קורא אותן לומר שאינו מפסיק בהן והכי איתא בירושלמי במגלה, ובמקומות הללו נהגו שהעולים לקרות בתורה הוא לבדו קורא ואין החזן קורא עמו, ומה שכתב הוא ענין זרות הוא מאד והצבור היכן הלכו עכ\"ל:",1,0]]);
